{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C07"],
      "claim": "Ketoprofen, a lipophilic acidic drug with low molecular weight and pKa near 4.5, has human oral bioavailability approaching 1.0; this directly supports high F for the query, which is also a low-molecular-weight acidic lipophilic drug.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Diflunisal, a salicylic acid derivative with a carboxylic acid and moderate lipophilicity, showed 89.5% absolute oral bioavailability versus IV in a volunteer; this supports high oral bioavailability for the acidic, moderately lipophilic query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C21"],
      "claim": "Ketoprofen absolute oral bioavailability was 92% versus IV for 100 mg capsules in humans, providing another direct high-F measurement for a small acidic drug and reinforcing the high-F prediction.",
      "evidence_role": "supportive"
    }
  ],
  "confidence": "high",
  "decision_summary": "The query is warfarin, a 4-hydroxycoumarin anticoagulant with near-complete oral absorption in humans. Supporting analogues with acidic, lipophilic, low-MW profiles (ketoprofen, diflunisal) show high absolute oral bioavailability, while low-F analogues such as baicalein, alendronate, and cromolyn are structurally dissimilar due to polyphenolic, bisphosphonate, or highly polar polyanionic features. The physicochemical prior also favors high F. Therefore predict high.",
  "evidence_gaps": [
    "No direct warfarin bioavailability record is included in the provided evidence set; all analogues have low Morgan similarity (<0.3).",
    "No direct measurements of first-pass metabolism or intestinal permeability for the query are provided."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

